// scripts/generate-classify-table.mjs — regenerates
// packages/core/src/classify/table-data.ts from
// fixtures/classify/tool-names.json, the single source of truth for the
// (agent, toolName) -> category table. Run it after editing the fixture so the
// committed core table and the fixture never drift; the drift test
// (packages/core/test/classify/fixture-rows.test.ts) fails loudly if they do.
// What this script must not do: classify anything or guess categories. It only
// shape-checks rows (so the generated file cannot emit garbage) and rejects a
// case-collision that would make the lowercased-name fallback ambiguous.

import { readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const rootDir = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const fixturePath = resolve(rootDir, "fixtures/classify/tool-names.json");
const outputPath = resolve(rootDir, "packages/core/src/classify/table-data.ts");

const CATEGORIES = new Set(["read", "search", "edit", "exec", "web", "other"]);

function rowShapeError(message, row) {
  return new Error(`${message}: ${JSON.stringify(row)}`);
}

const table = JSON.parse(readFileSync(fixturePath, "utf8"));
if (table.schema !== 1) {
  throw new Error(
    `fixtures/classify/tool-names.json schema must be 1, got ${JSON.stringify(table.schema)}`,
  );
}
if (!Array.isArray(table.rows)) {
  throw new Error("fixtures/classify/tool-names.json carries no rows array");
}

for (const row of table.rows) {
  if (typeof row.agent !== "string" || row.agent.length === 0)
    throw rowShapeError("row agent must be a non-empty string", row);
  if (typeof row.toolName !== "string" || row.toolName.length === 0)
    throw rowShapeError("row toolName must be a non-empty string", row);
  if (!CATEGORIES.has(row.category))
    throw rowShapeError("row category is not a documented category", row);
  if (typeof row.verified !== "boolean") throw rowShapeError("row verified must be a boolean", row);
  if (row.note !== undefined && typeof row.note !== "string")
    throw rowShapeError("row note must be a string when present", row);
}

const lowercaseKeys = new Set();
for (const row of table.rows) {
  const key = `${row.agent}\u0000${row.toolName.toLowerCase()}`;
  if (lowercaseKeys.has(key)) {
    throw new Error(
      `fixtures/classify/tool-names.json has a case-collision on ${key}; the lowercased-name fallback would be ambiguous`,
    );
  }
  lowercaseKeys.add(key);
}

function formatRow(row) {
  const fields = [
    `agent: ${JSON.stringify(row.agent)}`,
    `toolName: ${JSON.stringify(row.toolName)}`,
    `category: ${JSON.stringify(row.category)}`,
    `verified: ${row.verified ? "true" : "false"}`,
  ];
  if (row.note !== undefined) {
    fields.push(`note: ${JSON.stringify(row.note)}`);
  }
  return `  { ${fields.join(", ")} },`;
}

const rows = table.rows.map(formatRow).join("\n");
const output = [
  "// Generated by scripts/generate-classify-table.mjs from",
  "// fixtures/classify/tool-names.json. Do not edit by hand; edit the fixture",
  "// and rerun the generator. Consumers that need the lookup use",
  "// ./table.js, never this module directly.",
  "export const TOOL_NAME_ROWS = [",
  rows,
  "] as const;",
  "",
].join("\n");

writeFileSync(outputPath, output);
console.log(`generated ${outputPath} (${table.rows.length} rows)`);
